import java.util.*;
import java.io.*;

public class Main {
    static List<String> routeAnswers(String rates, String[][] queries) {
        // Write your solution here
        List<String> res = new ArrayList<>();
        for (int i = 0; i < queries.length; i++) res.add("-1");
        return res;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String rates = br.readLine().trim();
        int q = Integer.parseInt(br.readLine().trim());
        String[][] queries = new String[q][2];
        for (int i = 0; i < q; i++) {
            StringTokenizer st = new StringTokenizer(br.readLine());
            queries[i][0] = st.nextToken();
            queries[i][1] = st.nextToken();
        }
        StringBuilder sb = new StringBuilder();
        for (String s : routeAnswers(rates, queries)) sb.append(s).append("\n");
        System.out.print(sb);
    }
}
